import{_ as t,c as o,o as a,ah as n,ao as p,ap as s}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"彩虹橋的彼端——神與一切活物所立的約","description":"「彩虹橋」的說法很美，而聖經裡的彩虹更美：那是神與一切活物所立永遠的約。","frontmatter":{"title":"彩虹橋的彼端——神與一切活物所立的約","description":"「彩虹橋」的說法很美，而聖經裡的彩虹更美：那是神與一切活物所立永遠的約。"},"headers":[],"relativePath":"pets-in-heaven/rainbow-bridge-covenant.md","filePath":"pets-in-heaven/rainbow-bridge-covenant.md"}'),i={name:"pets-in-heaven/rainbow-bridge-covenant.md"};function r(l,e,h,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>「大家都說牠走過彩虹橋了。可是，這只是好聽的話，還是真的有盼望？」</p><p class="pl-quote-soft">有意思的是，聖經裡真的有彩虹——而且那約，是為動物立的。</p></div><section class="pl-section"><h2>一、那一道彩虹，是為動物立的</h2><p>洪水之後，神與挪亞立約，說祂不再用洪水毀滅全地。但祂立約的對象，不只是挪亞和他的子孫：</p><blockquote><p><strong>創世記 9:9-13</strong></p><p>&quot;And I, behold, I establish my covenant with you, and with your seed after you; And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you… And the bow shall be in the cloud; and it shall be for a token of a covenant between me and the earth.&quot;</p></blockquote><p>請留意「<em>every living creature</em>」——神把飛鳥、牲畜、地上一切的走獸，都列進了立約的對象。祂甚至把彩虹放在雲中，作為<strong>與大地、與一切活物</strong>的記號。</p><p>在整本聖經裡，這是一個極少被注意、卻極其溫柔的事實：<strong>神曾經正式地、永遠地，與動物立約。</strong></p><p>所以在人的想像裡有了「彩虹橋」這個名字，其實並不那麼離題。那道光，聖經說就是一個記號——記號的意義從來不是「結束」，而是「還有下文」。</p></section><section class="pl-section"><h2>二、在將來的世界裡，牠們可以安然躺臥</h2><p>先知以賽亞描述神要造的新世界時，畫面的主角之一是動物：</p><blockquote><p><strong>以賽亞書 65:25</strong></p><p>&quot;The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock… They shall not hurt nor destroy in all my holy mountain, saith the LORD.&quot;</p></blockquote><p>啟示錄則讓我們聽見，在那個最後的敬拜裡，有誰在唱歌：</p><blockquote><p><strong>啟示錄 5:13</strong></p><p>&quot;And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.&quot;</p></blockquote><p>「一切受造之物」都在敬拜。不是只有人。</p><p>而詩篇用一句最短的話總結了這件事：</p><blockquote><p><strong>詩篇 150:6</strong></p><p>&quot;Let every thing that hath breath praise the LORD.&quot;</p></blockquote><p>凡有氣息的——包括牠——都在那首歌裡面。</p></section><section class="pl-section"><h2>三、所以彩虹橋的彼端，是神的應許</h2><p>我們不能替神多做應許，但我們可以停留在祂已經說的話裡：祂與一切活物立了約；祂要造的世界裡有動物和平共存；祂最後的敬拜裡有「一切受造之物」；凡有氣息的都要讚美祂。</p><p>這些經文沒有說「你的牠一定在那裡」。但它們讓一句話變得完全可以禱告：「主啊，願祢的應許裡有牠。」而祂是那位連彩虹都願意為動物留下的神。</p><p class="pl-quote-soft">想一想：如果神願意為動物留下彩虹，祂怎麼會不記得牠？</p></section><div class="pl-quote"><p>「祢曾把彩虹放在雲中，作為與一切活物所立的記號。<br>今天我看見那道光的時候，我會想起牠。<br>願牠在祢的應許裡有平安，如同祢所應許的。<br>也願我在想念牠的日子裡，被祢的約托住。阿們。」</p></div><section class="pl-section"><h2>給你的一個小儀式</h2><p>下雨後若有彩虹出現，那可以是你們的記號。站在那裡幾秒鐘，對牠說話——不必有結論，不必說得完整。那道光在聖經裡本來就是「約的記號」，而記號的意思是：神沒有忘記。</p><p><a href="/pets-in-heaven/">← 回到 Pets in Heaven</a> ｜ 下一篇：<a href="/pets-in-heaven/permission-to-grieve">允許自己悲傷</a></p></section><div class="pl-cta"><h2>留下一起看過的風景。</h2><p>把牠的照片做成紀念卡片、海報或一段影片，讓那些一起走過的日子，有一個可以保存的樣子。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下載</a></div><div class="pl-bible"><h3>讓聖經的話繼續陪你</h3><p>本文引用的經文都出自聖經。用《彩虹聖經》隨時閱讀神的話、設定每日經文小工具，在想念牠的日子裡仍有一盞燈。</p><div class="pl-bible-shots"><figure><img src="'+p+'" alt="Rainbow Bible 聖經小工具顯示 2 Timothy 2:13" loading="lazy"><figcaption>每日經文放在主畫面</figcaption></figure><figure><img src="'+s+'" alt="Rainbow Bible App 的「天堂裡的毛孩」主題，顯示 Matthew 10:29-31" loading="lazy"><figcaption>切換到「天堂裡的毛孩」主題讀經</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 取得《彩虹聖經》</a></div>',8)])])}const v=t(i,[["render",r]]);export{g as __pageData,v as default};
